contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the minimal sequence: check precondition, call Deposit with value, then assert balance increased
    function run(address depositor, uint amt) public payable {
        // ensure this contract holds the funds to forward
        require(address(this).balance >= amt, "insufficient funds for test");
        // read old balance via public getter
        uint oldBal = c.balances(depositor);
        // make the Deposit call on behalf of this contract's caller: we must call from this contract, so ensure depositor equals address(this)
        // enforce that depositor is this contract to match msg.sender in c
        require(depositor == address(this), "depositor must be this contract");

        // perform the state-changing call: forward amt wei to c.Deposit()
        c.Deposit{value: amt}();

        // read new balance
        uint newBal = c.balances(depositor);

        // invariant: new balance equals old balance plus amt (holds in P, broken in mutant M)
        assert(newBal == oldBal + amt);
    }

    // allow funding this contract so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive contract: first deposit some initial amount, then deposit more; assert the second deposit increases stored balance by exactly that second amount.
    function runTest(uint initial, uint more) public payable {
        // need enough Ether in this contract to forward both deposits
        require(address(this).balance >= initial + more, "insufficient balance for test");

        // initial deposit by forwarding Ether
        c.Deposit{value: initial}();

        // read balance after initial deposit
        uint bal_before = c.balances(address(this));

        // second deposit of 'more'
        c.Deposit{value: more}();

        // read balance after second deposit
        uint bal_after = c.balances(address(this));

        // The property: the balance increased by exactly 'more'
        assert(bal_after == bal_before + more);
    }

    // Allow funding this test contract so it can call c.Deposit with value
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing the minimal sequence:
    // - ensure this test contract has enough ETH (caller funds it off-chain)
    // - call c.Deposit sending amount 'amt' from this contract
    // - read balances for this contract (msg.sender in c.Deposit) and check it increased by amt

    function runTest(uint amt) public payable {
        // Precondition: the caller provided ETH to this call so the test contract can forward it
        require(msg.value >= amt, "insufficient funding for amt");

        // observe balance before
        uint before = c.balances(address(this));

        // perform the state-changing call: Deposit must be invoked with value amt
        c.Deposit{value: amt}();

        // observe balance after
        uint after = c.balances(address(this));

        // The invariant: the recorded balance for the caller increased by exactly amt
        assert(after == before + amt);
    }

    // Allow the test contract to receive ETH so callers can fund it before calling runTest
    receive() external payable {}
}

