pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: depositor (actor) and deposit amount
    function testFuzz_property(address depositor, uint96 amount) public {
        // keep amount non-zero and within reasonable bounds
        vm.assume(depositor != address(0));
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        // fund depositor and perform deposit as depositor
        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.Deposit{value: amt}();

        // record balance slot for depositor and for tx.origin (which in this test equals depositor)
        uint256 before_depositor = c.balances(depositor);

        // ensure MinSum is low enough so Collect can proceed
        // MinSum initially 1 ether in reference; if amt < MinSum Collect would be a no-op; we want to allow Collect
        // so set MinSum to a small value before initializing
        vm.prank(address(this));
        c.SetMinSum(1);

        // call Collect as depositor to withdraw the full amount
        vm.prank(depositor);
        bool ok;
        try c.Collect(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful Collect, the depositor's recorded balance must have decreased by exactly amt
        // If Collect reverted (ok==false) then the reference still guarantees balances unchanged; both cases
        // are captured by the single assert: either Collect succeeded and balance decreased by amt, or Collect failed
        // and balance remains as before. We assert that the reference's observed balances(depositor) is either
        // before_depositor - amt (when ok) or before_depositor (when not ok).

        uint256 after_depositor = c.balances(depositor);

        // Single assertion that specifies the invariant the reference satisfies for all inputs
        if (ok) {
            assertTrue(after_depositor + amt == before_depositor);
        } else {
            assertTrue(after_depositor == before_depositor);
        }
    }
}
